import { z } from 'zod';
import type { Repo } from '../db/repo.js';
import { buildRunStory } from '../engine/story.js';
import type { Gateway } from '../models/gateway.js';
import type { TableStore } from '../tables/store.js';

// M5 Task 6: "explain anything". The web's `?` buttons and alt-clicks POST
// here; the answer is 2–3 plain-English sentences about this business's
// actual data, generated by the builder model from the looked-up facts.
// Lookup idioms (repo/tables calls, "Unknown X" strings) mirror the builder
// agent's `explain` tool, which serves the agent's own lookups instead.

export const ExplainBody = z
  .object({
    kind: z.enum(['step', 'run', 'table', 'column', 'ui']),
    id: z.string().optional(),
    context: z.string().optional(),
  })
  .strict();

export type ExplainRequest = z.infer<typeof ExplainBody>;

/** Carries the HTTP status for a failed explanation (400/404). */
export class ExplainError extends Error {
  status: 400 | 404;
  constructor(message: string, status: 400 | 404) {
    super(message);
    this.name = 'ExplainError';
    this.status = status;
  }
}

/**
 * Fixed descriptions for UI controls, one per `data-explain` key. These need
 * no model call (nothing business-specific to say) and no cache entry (they
 * are constants) — returned directly.
 */
export const UI_DESCRIPTIONS: Record<string, string> = {
  'mode-switch':
    'Design is where you build and change the chore reducer with your helper. Watch it run shows what it actually did, run by run.',
  'turn-on':
    'Turn on starts the chore reducer so it watches for new work on its own. You can turn it off again any time.',
  'nav-inbox':
    'Inbox shows everything your chore reducers have done, newest first — like an email inbox for your business.',
  'nav-automate':
    'Automate is where you describe a chore and build a new chore reducer, and see your reducers and pinned numbers at a glance.',
  'nav-data': 'Data is the things your business keeps track of, like customers and bookings.',
  'nav-settings':
    'Settings is where you tell the app about your business and how you want it to look and sound.',
};

const EXPLAIN_SYSTEM =
  'You explain one thing about a small family business to its owner, who is not technical. ' +
  'Answer in 2–3 short plain-English sentences about the facts given. ' +
  'No jargon, no ids, no JSON, no preamble.';

const ExplainText = z.object({ text: z.string() });

export interface ExplainerDeps {
  gateway: Gateway;
  repo: Repo;
  tables: TableStore;
}

function requireId(id: string | undefined, what: string): string {
  if (id === undefined || id === '') throw new ExplainError(`Say which ${what} to explain.`, 400);
  return id;
}

/** Newest row updated_at ('' when empty): in-place edits keep the row count, so the count alone would serve stale prose. ISO strings compare lexicographically. */
function latestUpdate(rows: Record<string, unknown>[]): string {
  let latest = '';
  for (const row of rows) {
    const u = row['updated_at'];
    if (typeof u === 'string' && u > latest) latest = u;
  }
  return latest;
}

/**
 * One explainer per app instance; the cache is the instance's in-memory Map.
 * Keys carry a freshness component per prompt input: version + latest run id
 * for steps (the prompt quotes the latest run's why), the run status for
 * runs, the row count + newest updated_at for tables and columns (labels and
 * columns are immutable — the store has no rename — so count + edits cover
 * every prompt input).
 */
export function createExplainer(deps: ExplainerDeps): {
  explain(req: ExplainRequest): Promise<{ text: string }>;
} {
  const cache = new Map<string, string>();

  async function viaGateway(key: string, user: string): Promise<{ text: string }> {
    const hit = cache.get(key);
    if (hit !== undefined) return { text: hit };
    const result = await deps.gateway.chatJson({
      role: 'builder',
      system: EXPLAIN_SYSTEM,
      user,
      schema: ExplainText,
      schemaName: 'explain',
    });
    cache.set(key, result.data.text);
    return { text: result.data.text };
  }

  async function explainStep(id: string | undefined, context: string | undefined) {
    const stepId = requireId(id, 'step');
    const workflowId = requireId(context, 'chore reducer');
    const wf = deps.repo.getWorkflow(workflowId);
    if (!wf) throw new ExplainError(`Unknown workflow: ${workflowId}`, 404);
    const node = wf.trigger.id === stepId ? wf.trigger : wf.steps.find((s) => s.id === stepId);
    if (!node) throw new ExplainError(`Unknown step: ${stepId}`, 404);
    // The most recent live run's record for this step (listRuns is newest
    // first); a step that never ran explains from its settings alone. The
    // scan is bounded (Dad-scale: past 100 runs the step explains from
    // settings alone) and the winning run id joins the cache key, so a new
    // run with a fresh why invalidates.
    let lastWhy: string | undefined;
    let lastRunId = '';
    for (const run of deps.repo.listRuns({ workflowId, limit: 100 })) {
      const full = deps.repo.getRun(run.id);
      const match = full?.steps.find((s) => s.stepId === stepId);
      if (match?.why) {
        lastWhy = match.why;
        lastRunId = run.id;
        break;
      }
    }
    const user =
      `Step "${node.title}" (${node.type}): ${node.summary}\n` +
      `Settings: ${JSON.stringify(node.config)}\n` +
      `Last run: ${lastWhy ?? 'It has not run yet.'}`;
    return viaGateway(`step|${workflowId}|${stepId}|v${wf.version}|r${lastRunId}`, user);
  }

  async function explainRun(id: string | undefined) {
    const runId = requireId(id, 'run');
    const full = deps.repo.getRun(runId);
    if (!full) throw new ExplainError(`Unknown run: ${runId}`, 404);
    // The run's OWN pinned version, like GET /api/runs/:id.
    const wf = deps.repo.getWorkflow(full.run.workflowId, full.run.workflowVersion);
    const story = wf
      ? buildRunStory(wf, full.steps, { usedSample: full.run.usedSample }).join('\n')
      : 'The workflow version is gone.';
    const user = `Run ${runId} (${full.run.status}):\n${story}`;
    return viaGateway(`run|${runId}|${full.run.status}`, user);
  }

  async function explainTable(id: string | undefined) {
    const name = requireId(id, 'list');
    const t = deps.tables.getTable(name);
    if (!t) throw new ExplainError(`Unknown table: ${name}`, 404);
    const rows = deps.tables.query(name);
    const count = rows.length;
    const cols = t.columns.map((c) => `${c.label} (${c.type})`).join(', ');
    const user = `List "${t.label}" with ${count} row${count === 1 ? '' : 's'} and columns ${cols}.`;
    return viaGateway(`table|${name}|n${count}|u${latestUpdate(rows)}`, user);
  }

  async function explainColumn(id: string | undefined, context: string | undefined) {
    const column = requireId(id, 'column');
    const table = requireId(context, 'list');
    const t = deps.tables.getTable(table);
    if (!t) throw new ExplainError(`Unknown table: ${table}`, 404);
    const col = t.columns.find((c) => c.name === column);
    if (!col) throw new ExplainError(`Unknown column: ${column}`, 404);
    const rows = deps.tables.query(table);
    const count = rows.length;
    const user =
      `Column "${col.label}" (${col.type}) in list "${t.label}", ` +
      `which holds ${count} row${count === 1 ? '' : 's'}.`;
    return viaGateway(`column|${table}|${column}|n${count}|u${latestUpdate(rows)}`, user);
  }

  return {
    async explain(req: ExplainRequest): Promise<{ text: string }> {
      switch (req.kind) {
        case 'step':
          return explainStep(req.id, req.context);
        case 'run':
          return explainRun(req.id);
        case 'table':
          return explainTable(req.id);
        case 'column':
          return explainColumn(req.id, req.context);
        case 'ui': {
          const key = requireId(req.id, 'control');
          const text = UI_DESCRIPTIONS[key];
          if (text === undefined) throw new ExplainError(`Unknown control: ${key}`, 404);
          return { text };
        }
      }
    },
  };
}
